{$ param number label="Step Number" default="1" description="Number shown in the badge." $}
{$ param title label="Title" default="Step Title" description="Step heading." $}

<div class="ss-step flex flex-col items-start p-4 border border-linework rounded-md bg-white mb-4">
  <div class="flex items-center mb-3">
    <span class="inline-flex items-center justify-center w-10 h-10 rounded-full bg-primary text-white font-bold mr-3">{$= number $}</span>
    <h3 class="text-lg mb-0 text-primary-dark">{$= title $}</h3>
  </div>
  {$ slot body $}
    <p class="ss-small text-neutral-dark">Step description.</p>
  {$ /slot $}
</div>
